const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '6 行 × 4 列（共 24 格）' },
      { kind: 'text', payload: '4 列' },
      { kind: 'text', payload: '6 行' }
    ];
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 480;
    var H = (input.viewport && input.viewport.heightDu) || 520;

    var cols = 4;
    var rows = 6;

    var left = 68;
    var right = W - 32;
    var top = 76;
    var bottom = H - 68;
    if (right - left < 40) { right = left + 40; }
    if (bottom - top < 40) { bottom = top + 40; }

    var dx = (right - left) / cols;
    var dy = (bottom - top) / rows;

    var paths = [];
    var i, id, x, y;

    for (i = 0; i <= cols; i++) {
      x = left + dx * i;
      id = 'v' + i;
      paths.push({ id: id, commands: [['M', x, top], ['L', x, bottom]] });
    }
    for (i = 0; i <= rows; i++) {
      y = top + dy * i;
      id = 'h' + i;
      paths.push({ id: id, commands: [['M', left, y], ['L', right, y]] });
    }

    paths.push({
      id: 'border',
      commands: [
        ['M', left, top],
        ['L', right, top],
        ['L', right, bottom],
        ['L', left, bottom],
        ['Z']
      ]
    });

    var children = [];
    var innerFill = '#9BB0C9';
    var outerFill = '#26354a';

    for (i = 0; i < paths.length; i++) {
      var pid = paths[i].id;
      if (pid === 'border') {
        children.push({
          type: 'path',
          pathId: pid,
          fill: outerFill,
          stroke: { width: 2.5, cap: 'butt', join: 'miter' }
        });
      } else {
        children.push({
          type: 'path',
          pathId: pid,
          fill: innerFill,
          stroke: { width: 1.2, cap: 'butt', join: 'miter' }
        });
      }
    }

    var midX = (left + right) / 2;
    var midY = (top + bottom) / 2;

    children.push({
      type: 'label',
      contentId: metrics[0].contentId,
      anchor: { x: midX, y: top - 26 },
      hAlign: 'center',
      vAlign: 'bottom',
      color: '#26354a'
    });
    children.push({
      type: 'label',
      contentId: metrics[1].contentId,
      anchor: { x: midX, y: bottom + 30 },
      hAlign: 'center',
      vAlign: 'top',
      color: '#26354a'
    });
    children.push({
      type: 'label',
      contentId: metrics[2].contentId,
      anchor: { x: left / 2, y: midY },
      hAlign: 'center',
      vAlign: 'middle',
      color: '#26354a'
    });

    return {
      schemaVersion: 1,
      sceneId: 'grid-6x4',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
